fn main() {
    let mut best = (0, 0);
    for i in 1..1_000_000u64 {
      let (mut n, mut s) = (i, 1);
      while n != 1 {
        n = if n % 2 == 0 { n / 2 }
            else { 3 * n + 1 };
        s += 1;
      }
      best = best.max((s, i));
    }
    println!("{best:?}");
}
